140	        }
141	        populateHouseholdMemberCount(owner);
142	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
148	        normalizeAndValidate(ownerFieldsDto);
149	        HttpHeaders headers = new HttpHeaders();
150	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
151	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
152	        owner.setNamesakeCount(countNamesakes(owner));
153	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
154	        assignHouseholdId(owner, ownerFieldsDto);
155	        this.clinicService.saveOwner(owner);
156	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
157	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
158	            MembershipLevelResolver.deriveMembershipLevel(owner.getEmail(), owner.getNamesakeCount()));
159	        populateHouseholdMemberCount(owner);
160	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
161	        headers.setLocation(UriComponentsBuilder.newInstance()
162	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
163	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
164	    }
165	
166	    /**
167	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
168	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
169	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
170	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
171	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
172	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
173	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
174	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
175	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly.
176	     *
177	     * @param ownerFieldsDto the incoming owner payload, mutated in place
178	     * @throws MissingOwnerFieldsException if any required field is missing or blank
179	     * @throws DuplicateTelephoneException if another owner already uses the normalized telephone
180	     */
181	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
182	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
183	        validateRequiredFields(ownerFieldsDto);
184	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
185	        ownerFieldsDto.setTelephone(telephone);
186	        requireUniqueTelephone(telephone);
187	        requireUniqueHousehold(ownerFieldsDto);
188	        requireCityHasCapacity(ownerFieldsDto.getCity());
189	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
190	        ownerFieldsDto.setRegistrationDate(registrationDate);
191	        requireDailyLimitNotReached(registrationDate);
192	        String email = emailNormalizer.normalize(ownerFieldsDto.getEmail());
193	        ownerFieldsDto.setEmail(email);
194	        requireUniqueEmail(email);
195	    }
196	
197	    /**
198	     * Rejects creating an owner whose normalized (lower-cased) email is already used by another owner. Existing owners'
199	     * stored emails are normalized the same way before comparison, so the rule holds regardless of the case the email
200	     * was originally supplied in. A missing (blank or {@code null}) email is never rejected, since the field is
201	     * optional.
202	     *
203	     * @param email the normalized email of the owner being created, may be {@code null}
204	     * @throws DuplicateEmailException if any existing owner already uses the same normalized email
205	     */
206	    private void requireUniqueEmail(String email) {
207	        if (email == null || email.isBlank()) {
208	            return;
209	        }
210	        boolean inUse = this.clinicService.findAllOwners().stream()
211	            .map(existing -> emailNormalizer.normalize(existing.getEmail()))
212	            .anyMatch(email::equals);
213	        if (inUse) {
214	            throw new DuplicateEmailException("email is already in use by another owner");
215	        }
216	    }
217	
218	    /**
219	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
220	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday or
221	     * Sunday it is rolled forward to the following Monday. The returned date is always a business day.
222	     *
223	     * @param ownerFieldsDto the incoming owner payload
224	     * @return the effective registration date rolled forward onto a business day
225	     */
226	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
227	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
228	        if (effective == null) {
229	            effective = LocalDate.now();
230	        }
231	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY) {
232	            effective = effective.plusDays(1);
233	        }
234	        return effective;
235	    }
236	
237	    /**
238	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
239	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
240	     * further owner may be created for that day.
241	     *
242	     * @param registrationDate the adjusted business-day registration date of the owner being created
243	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
244	     */
245	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
246	        long createdThatDay = this.clinicService.findAllOwners().stream()
247	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
248	            .count();
249	        if (createdThatDay >= MAX_OWNERS_PER_DAY) {
250	            throw new DailyOwnerLimitExceededException(
251	                "the maximum number of owners for today has already been reached");
252	        }
253	    }
254	
255	    /**
256	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
257	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
258	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
259	     * reflects only owners that predate it.
260	     *
261	     * @param registrationDate the adjusted business-day registration date of the owner being created
262	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
263	     */
264	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
265	        long createdThatDay = this.clinicService.findAllOwners().stream()
266	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
267	            .count();
268	        return createdThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
269	    }
270	
271	    /**
272	     * Builds an owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>}. {@code CITY3} is the upper-cased
273	     * first three letters of the city, {@code LAST3} the upper-cased first three letters of the last name, and
274	     * {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more than the number of owners already in that
275	     * city (e.g. {@code LON-SMI-0007}).
276	     *
277	     * @param city     the owner's city
278	     * @param lastName the owner's last name
279	     * @return the generated customer code
280	     */
281	    private String generateCustomerCode(String city, String lastName) {
282	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase();
283	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
284	        int sequence = (int) this.clinicService.findAllOwners().stream()
285	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
286	            .count() + 1;
287	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
288	    }
289	
290	    /**
291	     * Counts how many existing owners already share the given owner's first and last name, compared
292	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
293	     * create; it is zero when the owner's name is unique.
294	     *
295	     * @param owner the newly mapped owner about to be saved
296	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
297	     */
298	    private int countNamesakes(Owner owner) {
299	        String firstName = owner.getFirstName();
300	        String lastName = owner.getLastName();
301	        return (int) this.clinicService.findAllOwners().stream()
302	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
303	                && lastName.equalsIgnoreCase(existing.getLastName()))
304	            .count();
305	    }
306	
307	    /**
308	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
309	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
310	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
311	     *
312	     * @param ownerFieldsDto the owner payload to validate
313	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
314	     */
315	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
316	        List<String> missingFields = new ArrayList<>();
317	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
318	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
319	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
320	        requireText(missingFields, "city", ownerFieldsDto.getCity());
321	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
322	        if (!missingFields.isEmpty()) {
323	            throw new MissingOwnerFieldsException(missingFields);
324	        }
325	    }
326	
327	    private void requireText(List<String> missingFields, String fieldName, String value) {
328	        if (value == null || value.isBlank()) {
329	            missingFields.add(fieldName);
330	        }
331	    }
332	
333	    /**
334	     * Rejects creating an owner whose normalized telephone is already used by another owner. Existing owners' stored
335	     * telephones are canonicalized the same way before comparison, so the rule holds regardless of how their number was
336	     * originally formatted.
337	     *
338	     * @param telephone the normalized telephone of the owner being created
339	     * @throws DuplicateTelephoneException if any existing owner already uses the same normalized telephone
340	     */
341	    private void requireUniqueTelephone(String telephone) {
342	        boolean inUse = this.clinicService.findAllOwners().stream()
343	            .map(existing -> telephoneNormalizer.canonicalize(existing.getTelephone()))
344	            .anyMatch(telephone::equals);
345	        if (inUse) {
346	            throw new DuplicateTelephoneException("telephone is already in use by another owner");
347	        }
348	    }
349	
350	    /**
351	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
352	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
353	     *
354	     * @param city the city of the owner being created
355	     * @throws OwnerCityFullException if the city already contains 50 or more owners
356	     */
357	    private void requireCityHasCapacity(String city) {
358	        long cityOwners = this.clinicService.findAllOwners().stream()
359	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
360	            .count();
361	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
362	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
363	        }
364	    }
365	
366	    /**
367	     * Rejects creating an owner who shares a household (see {@link #findHouseholdMembers}) with an existing owner,
368	     * unless the request opts in by setting {@code sharesHousehold} to {@code true}.
369	     *
370	     * @param ownerFieldsDto the incoming owner payload
371	     * @throws DuplicateOwnerException if another owner already belongs to the same household and the request does not
372	     *                                 set {@code sharesHousehold}
373	     */
374	    private void requireUniqueHousehold(OwnerFieldsDto ownerFieldsDto) {
375	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
376	            return;
377	        }
378	        if (!findHouseholdMembers(ownerFieldsDto).isEmpty()) {
379	            throw new DuplicateOwnerException(
380	                "an owner with the same last name and address already exists in this household");
381	        }
382	    }
383	
384	    /**
385	     * Finds the existing owners that belong to the same household as the given payload, i.e. those sharing both its
386	     * last name and address. The last name is compared case-insensitively after collapsing runs of whitespace to a
387	     * single space and trimming; the address is compared in its normalized form (see {@link AddressNormalizer}), so
388	     * incidental formatting differences and abbreviation variants do not affect membership.
389	     *
390	     * @param ownerFieldsDto the incoming owner payload
391	     * @return the existing owners in the same household, in the order {@link ClinicService#findAllOwners()} returns
392	     *         them; empty when none match
393	     */
394	    private List<Owner> findHouseholdMembers(OwnerFieldsDto ownerFieldsDto) {
395	        String lastName = collapseWhitespace(ownerFieldsDto.getLastName());
396	        String address = addressNormalizer.normalize(ownerFieldsDto.getAddress());
397	        return this.clinicService.findAllOwners().stream()
398	            .filter(existing -> collapseWhitespace(existing.getLastName()).equalsIgnoreCase(lastName)
399	                && addressNormalizer.normalize(existing.getAddress()).equals(address))
400	            .toList();
401	    }
402	
403	    /**
404	     * Canonicalizes a value for household comparison by trimming it and collapsing every run of whitespace to a single
405	     * space. Case is deliberately preserved here; callers compare the result case-insensitively.
406	     *
407	     * @param value the raw field value, may be {@code null}
408	     * @return the whitespace-collapsed value, or an empty string when {@code null}
409	     */
410	    private String collapseWhitespace(String value) {
411	        if (value == null) {
412	            return "";
413	        }
414	        return value.strip().replaceAll("\\s+", " ");
415	    }
416	
417	    /**
418	     * Assigns the shared {@code householdId} for an owner joining an existing household. Only owners created with
419	     * {@code sharesHousehold} set to {@code true} that actually match an existing household (see
420	     * {@link #findHouseholdMembers}) are given an identifier; single owners keep a {@code null} household. The
421	     * identifier is derived deterministically from the household's last name and address (see
422	     * {@link IdentityKeyResolver#deriveHouseholdId}), so every member of the same household resolves to the same stable
423	     * value regardless of creation order. Existing members that predate the feature and still lack the identifier are
424	     * backfilled (see {@link #backfillHouseholdMembers}) so the whole household shares it.
425	     *
426	     * @param owner          the newly mapped owner about to be saved
427	     * @param ownerFieldsDto the incoming owner payload
428	     */
429	    private void assignHouseholdId(Owner owner, OwnerFieldsDto ownerFieldsDto) {
430	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
431	            return;
432	        }
433	        List<Owner> members = findHouseholdMembers(ownerFieldsDto);
434	        if (members.isEmpty()) {
435	            return;
436	        }
437	        String householdId =
438	            identityKeyResolver.deriveHouseholdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
439	        owner.setHouseholdId(householdId);
440	        backfillHouseholdMembers(householdId, members);
441	    }
442	
443	    /**
444	     * Stamps the shared {@code householdId} onto the existing members of a household that do not already carry it,
445	     * persisting each one that changes. Members that predate the feature (and so still lack the identifier) are brought
446	     * into line so the whole household shares the single value; members that already carry it are left untouched.
447	     *
448	     * @param householdId the shared household identifier
449	     * @param members     the existing owners in the household
450	     */
451	    private void backfillHouseholdMembers(String householdId, List<Owner> members) {
452	        for (Owner member : members) {
453	            if (!householdId.equals(member.getHouseholdId())) {
454	                member.setHouseholdId(householdId);
455	                this.clinicService.saveOwner(member);
456	            }
457	        }
458	    }
459	
460	    /**
461	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
462	     * household, i.e. those sharing the same non-null {@code householdId} (including the owner itself). An owner with no
463	     * household is counted as a household of one.
464	     *
465	     * @param owner the owner whose household size should be resolved
466	     */
467	    private void populateHouseholdMemberCount(Owner owner) {
468	        String householdId = owner.getHouseholdId();
469	        if (householdId == null) {
470	            owner.setHouseholdMemberCount(1);
471	            return;
472	        }
473	        long members = this.clinicService.findAllOwners().stream()
474	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
475	            .count();
476	        owner.setHouseholdMemberCount((int) members);
477	    }
478	
479	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
480	    @Override
481	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
482	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
483	        if (currentOwner == null) {
484	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
485	        }
486	        currentOwner.setAddress(ownerFieldsDto.getAddress());
487	        currentOwner.setCity(ownerFieldsDto.getCity());
488	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
489	        currentOwner.setLastName(ownerFieldsDto.getLastName());
490	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
491	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
492	        this.clinicService.saveOwner(currentOwner);
493	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
494	    }
495	
496	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
497	    @Transactional
498	    @Override
499	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
500	        Owner owner = this.clinicService.findOwnerById(ownerId);
501	        if (owner == null) {
502	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
503	        }
504	        this.clinicService.deleteOwner(owner);
505	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
506	    }
507	
508	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
509	    @Override
510	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
511	        Owner owner = this.clinicService.findOwnerById(ownerId);
512	        if (owner == null) {
513	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
514	        }
515	        HttpHeaders headers = new HttpHeaders();
516	        Pet pet = petMapper.toPet(petFieldsDto);
517	        owner.setId(ownerId);
518	        pet.setOwner(owner);
519	        pet.getType().setName(null);
520	        this.clinicService.savePet(pet);
521	        PetDto petDto = petMapper.toPetDto(pet);
522	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
523	            .buildAndExpand(pet.getId()).toUri());
524	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
525	    }
526	
527	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
528	    @Override
529	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
530	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
531	        if (currentOwner != null) {
532	            Pet currentPet = this.clinicService.findPetById(petId);
533	            if (currentPet != null) {
534	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
535	                currentPet.setName(petFieldsDto.getName());
536	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
537	                this.clinicService.savePet(currentPet);
538	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
539	            }
540	        }
541	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
542	    }
543	
544	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
545	    @Override
546	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
547	        HttpHeaders headers = new HttpHeaders();
548	        Visit visit = visitMapper.toVisit(visitFieldsDto);
549	        Pet pet = new Pet();
550	        pet.setId(petId);
551	        visit.setPet(pet);
552	        this.clinicService.saveVisit(visit);
553	        VisitDto visitDto = visitMapper.toVisitDto(visit);
554	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
555	            .buildAndExpand(visit.getId()).toUri());
556	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
557	    }
558	
559	
560	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
561	    @Override
562	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
563	        Owner owner = this.clinicService.findOwnerById(ownerId);
564	        if (owner != null) {
565	            Pet pet = owner.getPet(petId);
566	            if (pet != null) {
567	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
568	            }
569	        }
570	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
571	    }
572	}
